using Json=nlohmann::json;
inline unsigned checks=0;
void require(bool yes,const char*why){if(!yes)throw std::runtime_error(why);++checks;}
Json settings(const ObjectBakeSettings&s){return{{"front_mm",s.front_mm},{"back_mm",s.back_mm},{"ao_distance_mm",s.ao_distance_mm},{"ao_samples",s.ao_samples},{"padding",s.padding},{"allow_partial",s.allow_partial},{"allow_backfaces",s.allow_backfaces},{"prepare_colors",s.prepare_colors},{"color_error",s.color_error},{"prepare_normals",s.prepare_normals},{"normal_error",s.normal_error},{"cage_object",s.cage_object}};}
ObjectBakeSettings route_settings(bool desktop){ObjectBakeSettings s;s.prepare_normals=true;if(desktop){auto distance=[](float v){return float(bake_distance_from_unit(bake_distance_to_unit(v)));};s.front_mm=distance(s.front_mm);s.back_mm=distance(s.back_mm);s.ao_distance_mm=distance(s.ao_distance_mm);constexpr double degrees=57.29577951308232;const double slider=double(s.normal_error)*degrees/(.25*degrees);s.normal_error=float(slider*(.25*degrees)/degrees);}return s;}
Json retained_sources(const Scene&scene,uint64_t target_id){auto copy=scene.snapshot();copy.erase(target_id);return copy.encode();}
Json normal_oracle(const Scene&scene,uint64_t source_id,uint64_t target_id){
 const auto&source=scene.object(source_id);const auto&target_object=scene.object(target_id);require(source.material_bindings&&source.material_bindings->normal_preparation&&source.painted->normal_projection()&&source.painted->baked(),"Public source must own genuine first-Bake normal authority");require(target_object.painted->normal_projection()&&target_object.painted->baked(),"Public accepted target must own actual second-Bake normal planes");const auto&mesh=target_object.painted->mesh();const auto a=source.painted->encode().at("mesh"),b=target_object.painted->encode().at("mesh");require(a.at("positions")==b.at("positions")&&a.at("indices")==b.at("indices")&&a.at("uv")==b.at("uv"),"Independent public normal comparison requires exact corresponding geometry/UVs");double maximum=0;size_t interior=0;
 for(size_t y=0;y<64;++y)for(size_t x=0;x<64;++x){const std::array<double,2> q{(x+.5)/64.,(y+.5)/64.};for(size_t tri=0;tri<mesh.indices.size()/3;++tri){const auto p=mesh.uv[mesh.indices[tri*3]],r=mesh.uv[mesh.indices[tri*3+1]],s=mesh.uv[mesh.indices[tri*3+2]];const double d=(r[1]-s[1])*(p[0]-s[0])+(s[0]-r[0])*(p[1]-s[1]);require(std::isfinite(d)&&std::abs(d)>1e-20,"Independent public UV determinant must be finite and nonsingular");const double u=((r[1]-s[1])*(q[0]-s[0])+(s[0]-r[0])*(q[1]-s[1]))/d,v=((s[1]-p[1])*(q[0]-s[0])+(p[0]-s[0])*(q[1]-s[1]))/d;require(std::isfinite(u)&&std::isfinite(v)&&std::isfinite(1-u-v),"Independent public barycentric coordinates must be finite");if(std::min({u,v,1-u-v})<.06)continue;const std::array<float,3>bary{float(u),float(v),float(1-u-v)};for(size_t role=0;role<2;++role){const auto expected=direction(source,tri,bary,role),actual=direction(target_object,tri,bary,role);finite_sample(expected);finite_sample(actual);for(size_t k=0;k<3;++k)maximum=std::max(maximum,std::abs(expected[k]-actual[k]));}++interior;break;}}
 require(interior>500&&std::isfinite(maximum)&&maximum<.035,"Independent finite public second-Bake normal decoder must satisfy the unchanged .035 bound");return{{"interior_texels",interior},{"maximum_component_error",maximum},{"maximum_allowed_error",.035},{"finite_samples",true},{"oracle","Independent double-precision actual first-prepared image/frame decoder, not product source resolver or renderer output"}};
}
void write_json(const std::filesystem::path&p,const Json&j){std::ofstream out(p);out<<j.dump(2)<<'\n';if(!out)throw std::runtime_error("Public prepared-source manifest write failed");}
