 auto f=fixture(legacy,posed);Case c;c.legacy=legacy;c.posed=posed;c.original=f.source;const std::string suffix=std::string(legacy?"MT0 ":"MT1 ")+(posed?"posed":"rest");f.scene.object(c.original).name="Original "+suffix;const auto original=f.scene.encode().at("objects").front();const auto original_paint=f.scene.object(c.original).painted;const auto original_binding=f.scene.object(c.original).material_bindings;const auto original_deformation=f.scene.object(c.original).deformation;const auto low=f.scene.object(c.original).deformation->preview(f.scene.object(c.original).painted->mesh());c.prepared=target(f.scene,low,legacy);f.scene.object(c.prepared).name="Prepared "+suffix;f.scene.select(c.prepared);const auto first=bake_object(f.scene,c.original,route_settings(false));const auto&prepared=f.scene.object(c.prepared);
 require(first.projected>0&&first.normal_prepared&&prepared.bake_recipe&&prepared.bake_recipe->source.object==c.original&&prepared.bake_recipe->source.original_object==c.original,"Public prepared source must be generated by a real first Bake with retained original source provenance");require(prepared.painted->normal_projection()&&prepared.painted->normal_projection()->version==1&&!prepared.painted->source_sampling_prepared()&&prepared.material_bindings&&prepared.material_bindings->normal_preparation&&!prepared.material_bindings->normal_preparation->uv_reprojection&&!prepared.material_bindings->normal_preparation->sampling_domain,"Public prepared source must be the supported genuine ordinary v1 normal state");auto retained_original=f.scene.snapshot();retained_original.erase(c.prepared);require(retained_original.encode().at("objects").front()==original&&f.scene.object(c.original).painted==original_paint&&f.scene.object(c.original).material_bindings==original_binding&&f.scene.object(c.original).deformation==original_deformation,"First Bake must preserve the complete original source and exact immutable owners");c.destination=target(f.scene,prepared.painted->mesh(),legacy);f.scene.object(c.destination).name="Destination "+suffix;f.scene.select(c.destination);c.before=std::move(f.scene);c.before.validate();require(c.before.objects().size()==3&&Scene::decode(c.before.encode()).encode()==c.before.encode(),"Public before capsule retains all three genuine source/prepared/destination objects exactly");Document doc;doc.replace(c.before.snapshot());require(doc.wait_mesh()&&doc.frame().state->can_bake&&doc.frame().state->bake_source==c.original&&std::find(doc.frame().state->bake_sources.begin(),doc.frame().state->bake_sources.end(),c.prepared)!=doc.frame().state->bake_sources.end(),"Public UI must initially default to Original while genuinely offering Prepared, requiring an explicit source choice");return c;
