 return{{"verified",true},{"case",manifest.at("case")},{"route",route},{"phase",phase},{"original_source",original},{"prepared_source",prepared},{"destination",destination},{"all_sources_and_first_recipe_exact",true},{"normal_oracle",oracle},{"checks",checks}};
